import torch


def run(inp, target, reduction, beta):
    return torch.ops.aten.smooth_l1_loss(
        inp, target, reduction, beta
    )


def run_correctness(inp, target, reduction, beta):
    output = torch.ops.aten.smooth_l1_loss(
        inp.float(), target.float(), reduction, beta
    )
    return output.to(inp.dtype)
